-- Generated by scripts/dbChangeTriggers.ts. Do not edit.
CREATE OR REPLACE FUNCTION db_change_capture()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  capture_enabled boolean;
BEGIN
  IF current_setting('app.skip_change_events', true) = txid_current()::text THEN
    RETURN NULL;
  END IF;

  SELECT enabled INTO capture_enabled FROM db_change_config WHERE id = 1;
  IF capture_enabled IS NOT TRUE THEN
    RETURN NULL;
  END IF;

  INSERT INTO db_change (table_name, row_key, op, old_row, new_row)
  VALUES (
    TG_TABLE_NAME,
    (
      SELECT jsonb_object_agg(key, value)
      FROM jsonb_each(
        CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END
      )
      WHERE key = ANY (TG_ARGV)
    ),
    lower(TG_OP),
    CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END,
    CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END
  );

  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS "campaign_db_change" ON "campaign";
DROP TRIGGER IF EXISTS "campaign_db_change_insert" ON "campaign";
DROP TRIGGER IF EXISTS "campaign_db_change_update" ON "campaign";
DROP TRIGGER IF EXISTS "campaign_db_change_delete" ON "campaign";
CREATE TRIGGER "campaign_db_change_insert" AFTER INSERT ON "campaign"
  FOR EACH ROW EXECUTE FUNCTION db_change_capture('id');
CREATE TRIGGER "campaign_db_change_update" AFTER UPDATE ON "campaign"
  FOR EACH ROW
  WHEN (OLD.* IS DISTINCT FROM NEW.*) EXECUTE FUNCTION db_change_capture('id');
DO $$
DECLARE
  stale record;
BEGIN
  FOR stale IN
    SELECT c.relname AS tbl, t.tgname AS trg
    FROM pg_trigger t
    JOIN pg_class c ON c.oid = t.tgrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND NOT t.tgisinternal
      AND t.tgname LIKE '%\_db\_change%'
      AND c.relname <> ALL (ARRAY['campaign']::text[])
  LOOP
    EXECUTE format('DROP TRIGGER %I ON %I', stale.trg, stale.tbl);
  END LOOP;
END $$;
